// ================= CENTRAL CONFIGURATION =================
// TEST_MODE = true  -> sends ONLY to test_recipients, adds a "TEST" banner,
//                      and does NOT mark the articles as sent. Always test first!
const TEST_MODE = true;

const tz = 'Africa/Casablanca';
const input = $input.first()?.json ?? {};
// Week comes from Agent 2 when called by the orchestrator, else the current week
const week = input.week || $now.setZone(tz).startOf('week').toISODate();
const wk = DateTime.fromISO(week, { zone: tz });
const baseId = `nl_${wk.weekYear}_w${String(wk.weekNumber).padStart(2, '0')}`;

return [{
  json: {
    test_mode: TEST_MODE,
    test_recipients: [
  { email: 'benkhajjousiham@gmail.com', first_name: 'Siham' },
  { email: 'ouiambenkhajou@gmail.com', first_name: 'Ouiam' },
  { email: 'mohammed.zelmati25@gmail.com', first_name: 'Mohammed' },
],
    newsletter_week: week,
    newsletter_id: TEST_MODE ? `${baseId}_test` : baseId,
    issue_number: wk.weekNumber,
    week_label: wk.setLocale('en').toFormat('d MMMM yyyy'),        // "21 September 2026"
    brand_name: 'AI Foundry Weekly',

    // ---- Recipients (used when TEST_MODE = false) ----
    // 'excel' -> reads the Excel file below   |   'list' -> uses recipients_list
    recipients_source: 'excel',
    recipients_file: '/files/recipients/ai_foundry_recipients.xlsx',
    recipients_list: [
      // { email: 'prenom.nom@nttdata.com', first_name: 'Prénom' },
    ],

    // ---- Gmail sender (must be the Gmail account of the SMTP credential) ----
    sender_email: 'benkhajjousiham@gmail.com',
    sender_name: 'AI Foundry Weekly',

    // ---- Assets ----
    logo_path: '/files/assets/ntt-data-logo.png',

    // ---- Optional (leave empty until the tracking/unsubscribe webhooks exist) ----
    unsubscribe_base_url: '',
    tracking_base_url: '',
  },
}];

// Validate + build tracking links (replaces the old mock + Validate + UTM nodes)
const cfg = $('Run Config').first().json;
const rows = $input.all().map(i => i.json).filter(r => r.article_id);

if (!rows.length) {
  throw new Error(`Aucun article 'selected' pour la semaine ${cfg.newsletter_week}. ` +
                  `Lancez l'Agent 2 d'abord, ou la newsletter a déjà été envoyée.`);
}

const campaign = cfg.newsletter_id.replace(/_test$/, '');

// When the feed gave no source name, derive it from the domain
const KNOWN_SOURCES = {
  'theverge.com': 'The Verge',
  'theaiinsider.tech': 'The AI Insider',
  'techcrunch.com': 'TechCrunch',
  'venturebeat.com': 'VentureBeat',
  'wired.com': 'Wired',
};
function sourceFromUrl(url) {
  const m = String(url || '').match(/^https?:\/\/(?:www\.)?([^\/?#:]+)/i);
  if (!m) return 'Unknown source';
  const host = m[1].toLowerCase();
  if (KNOWN_SOURCES[host]) return KNOWN_SOURCES[host];
  const name = host.split('.').slice(-2, -1)[0] || host;
  return name.charAt(0).toUpperCase() + name.slice(1);
}
const articles = rows.map((r, idx) => {
  // Built manually: URLSearchParams / URL are not available in the n8n Code sandbox
  const utm = Object.entries({
    utm_source: 'newsletter', utm_medium: 'email',
    utm_campaign: campaign, utm_content: r.article_id,
  }).map(([k, v]) => `${k}=${encodeURIComponent(v)}`).join('&');
  return {
    position: idx + 1,
    article_id: r.article_id,
    title: r.title || 'Untitled',
    source: r.source || sourceFromUrl(r.url),
    original_url: r.url,
    tracking_url: `${r.url}${r.url.includes('?') ? '&' : '?'}${utm}`,
    category: r.category || 'Other',
    summary: r.summary || '',
    relevance_score: Number(r.relevance_score),
    publication_date: r.published_date || '',
  };
});

return [{ json: { ...cfg, articles } }];

// Merge editorial content with the data. Every field has a fallback.
const data = $('Build Newsletter Data').first().json;
const ed = $input.first().json.output || {};

const shortMap = Object.fromEntries((ed.short_titles || []).map(s => [s.article_id, (s.short_title || '').trim()]));
const articles = data.articles.map(a => ({ ...a, short_title: shortMap[a.article_id] || a.title }));

// Fixed subject
const subject = `AI Foundry group: AI weekly news${data.test_mode ? ' [TEST]' : ''}`;

const trending = ed.trending?.title ? ed.trending : { title: articles[0].short_title, text: articles[0].summary };

// Image prompt built from the TRENDING news of the week
const visual = (ed.image_prompt || '').trim();
const image_prompt =
  `Editorial illustration for a corporate tech newsletter about this week's trending AI news: ` +
  `"${trending.title}". ${trending.text} ` +
  (visual ? `Visual concept: ${visual} ` : '') +
  `Style: premium tech magazine cover art, deep navy blue background, bright blue (#0172BB) and white light accents, ` +
  `cinematic lighting, minimalist, high detail. Square 1:1 composition. ` +
  `No text, no letters, no numbers, no logos, no brand names, no real people, no watermark.`;

return [{
  json: {
    ...data,
    articles,
    subject,
    introduction: (ed.introduction || '').trim() || `Here are the key AI news for the week of ${data.week_label}.`,
    trending,
    insights: (ed.insights || []).filter(Boolean).slice(0, 3),
    image_keywords: (ed.image_keywords || []).slice(0, 5),
    image_prompt,
  },
}];

// Validate the AI image. If generation failed, the newsletter is still sent
// with a gold "AI" block instead of the picture.
const item = $input.first();
const bin = item?.binary?.hero_image;
let has_hero = false, hero_warning = '';

if (bin) {
  const buf = await this.helpers.getBinaryDataBuffer(0, 'hero_image');
  if (buf.length > 1000 && buf.length < 5 * 1024 * 1024) {
    has_hero = true;
    bin.fileName = 'ai-foundry-weekly.png';
  } else {
    hero_warning = `Image invalide (${buf.length} octets)`;
  }
} else {
  hero_warning = "Génération d'image échouée : " + JSON.stringify(item?.json?.error ?? item?.json ?? '').slice(0, 200);
}

return [{ json: { has_hero, hero_warning }, binary: has_hero ? { hero_image: bin } : {} }];

// Gather both images on one item. The binary field names become the
// email CIDs:  hero_image -> <img src="cid:hero_image">,  ntt_logo -> cid:ntt_logo
const logoItem = $input.first();
const hero = $('Check AI Image').first();
const binary = {};
let has_logo = false;

if (logoItem?.binary?.ntt_logo) {
  binary.ntt_logo = { ...logoItem.binary.ntt_logo, fileName: 'ntt-data-logo.png' };
  has_logo = true;
}
if (hero.json.has_hero) binary.hero_image = hero.binary.hero_image;

return [{
  json: { has_logo, has_hero: hero.json.has_hero, hero_warning: hero.json.hero_warning },
  binary,
}];

// ============================================================
//  AI FOUNDRY WEEKLY — email template (Outlook / Gmail safe)
//  Tables + inline CSS only. No flex/grid, no CSS gradients.
//  Placeholders replaced per recipient: %%GREETING%%, %%UNSUBSCRIBE_URL%%, %%TRACKING_PIXEL%%
// ============================================================
function renderNewsletter(d) {
  // NTT DATA palette (logo blue #0172BB + deep navy)
  const C = {
    page: '#EEF3F8', paper: '#FFFFFF', ink: '#0A1F3C', gold: '#0172BB',
    goldSoft: '#E3EFF9', muted: '#4A5568', line: '#D9E4EF', dark: '#0A1F3C', white: '#FFFFFF',
  };
  const SERIF = "Georgia, 'Times New Roman', Times, serif";
  const SANS = "'Segoe UI', Arial, Helvetica, sans-serif";

  const L = { // labels
    tagline: 'THE LATEST. THE FUTURE.',
    bar: 'AI NEWS YOU NEED TO KNOW',
    week: 'WEEK OF',
    headlines: 'TOP STORIES THIS WEEK',
    read: 'READ ARTICLE',
    trending: 'TRENDING NOW',
    footer1: 'STAY INFORMED.', footer2: 'STAY AHEAD.',
    aiCaption: 'AI-generated illustration',
    test: 'TEST VERSION — not sent to the group',
  };

  const CAT = {
    'Research':             { icon: '🔬', label: 'RESEARCH' },
    'Product Launch':       { icon: '🚀', label: 'PRODUCT LAUNCH' },
    'Funding & Business':   { icon: '💼', label: 'BUSINESS' },
    'Policy & Regulation':  { icon: '⚖️', label: 'REGULATION' },
    'Tools & Applications': { icon: '🛠️', label: 'TOOLS' },
    'Other':                { icon: '📰', label: 'NEWS' },
  };

  const esc = s => String(s ?? '')
    .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;').replace(/'/g, '&#39;');
  const shortDate = iso => {
    if (!iso) return '';
    const dt = new Date(iso + 'T12:00:00Z');
    return isNaN(dt) ? '' : dt.toLocaleDateString('en-GB', { day: 'numeric', month: 'short' });
  };

  // ---------- one article card ----------
  const card = a => {
    const cat = CAT[a.category] || CAT.Other;
    const meta = [a.source, shortDate(a.publication_date)].filter(Boolean).map(esc).join(' · ');
    return `
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="border:1px solid ${C.line};background:${C.white};border-radius:6px;">
  <tr><td align="center" bgcolor="${C.dark}" style="background:${C.dark};border-radius:6px 6px 0 0;padding:18px 12px 16px 12px;">
    <div style="font-size:34px;line-height:40px;">${cat.icon}</div>
    <div style="font-family:${SANS};font-size:10px;letter-spacing:2px;color:#7CC4F0;font-weight:bold;padding-top:6px;">${cat.label}</div>
  </td></tr>
  <tr><td style="padding:16px 16px 18px 16px;">
    <div style="font-family:${SANS};font-size:14px;line-height:19px;font-weight:bold;color:${C.ink};text-transform:uppercase;letter-spacing:.4px;">${esc(a.short_title || a.title)}</div>
    <div style="font-family:${SANS};font-size:13px;line-height:20px;color:${C.muted};padding-top:8px;">${esc(a.summary)}</div>
    <div style="font-family:${SANS};font-size:11px;color:${C.gold};padding-top:10px;">${meta}</div>
    <table role="presentation" cellpadding="0" cellspacing="0" border="0" style="margin-top:14px;"><tr>
      <td style="border:1px solid ${C.gold};border-radius:3px;">
        <a href="${esc(a.tracking_url)}" target="_blank" style="display:inline-block;padding:8px 14px;font-family:${SANS};font-size:11px;font-weight:bold;letter-spacing:1.5px;color:${C.ink};text-decoration:none;">${L.read} &rarr;</a>
      </td>
    </tr></table>
  </td></tr>
</table>`;
  };

  // ---------- 2-column card grid ----------
  let grid = '';
  for (let i = 0; i < d.articles.length; i += 2) {
    const a = d.articles[i], b = d.articles[i + 1];
    grid += `
<tr>
  <td class="stack" width="50%" valign="top" style="padding:0 8px 16px 0;">${card(a)}</td>
  <td class="stack" width="50%" valign="top" style="padding:0 0 16px 8px;">${b ? card(b) : '&nbsp;'}</td>
</tr>`;
  }

  // ---------- header right side: AI image (or fallback) ----------
  const heroCell = d.has_hero
    ? `<img class="hero-img" src="cid:hero_image" width="230" height="230" alt="AI illustration of the week" style="display:block;width:230px;height:230px;border:1px solid ${C.gold};border-radius:6px;">
       <div style="font-family:${SANS};font-size:9px;line-height:13px;color:${C.muted};padding-top:6px;text-align:center;">${L.aiCaption}${d.image_keywords?.length ? ' · ' + esc(d.image_keywords.slice(0, 4).join(', ')) : ''}</div>`
    : `<table role="presentation" width="230" height="230" cellpadding="0" cellspacing="0" border="0" style="border-radius:6px;"><tr>
         <td align="center" valign="middle" bgcolor="${C.dark}" style="background:${C.dark};border-radius:6px;font-family:${SERIF};font-size:64px;color:#7CC4F0;height:230px;">AI</td>
       </tr></table>`;

  const logo = d.has_logo
    ? `<img src="cid:ntt_logo" height="28" alt="NTT DATA" style="display:block;height:28px;width:auto;border:0;">`
    : `<span style="font-family:${SANS};font-size:15px;font-weight:bold;color:#0172BB;letter-spacing:1px;">NTT DATA</span>`;

  // ---------- trending + insights ----------
  const insights = (d.insights || []).map((q, i) => `
    <div style="font-family:${SANS};font-size:13px;line-height:19px;color:${C.ink};padding:10px 0;${i < d.insights.length - 1 ? `border-bottom:1px solid ${C.goldSoft};` : ''}">${esc(q)}</div>`).join('');

  const pillars = [
    ['🧠', 'RESEARCH', 'Breakthroughs & papers'],
    ['🚀', 'PRODUCTS', 'Launches & tools'],
    ['💼', 'BUSINESS', 'Funding & market'],
    ['⚖️', 'REGULATION', 'Policy & ethics'],
  ].map(([ic, t, s], i) => `
    <td class="stack" width="25%" valign="top" style="padding:14px 6px;${i < 3 ? `border-right:1px solid ${C.line};` : ''}">
      <table role="presentation" cellpadding="0" cellspacing="0" border="0"><tr>
        <td valign="top" style="font-size:20px;padding-right:8px;">${ic}</td>
        <td valign="top" style="font-family:${SANS};">
          <div style="font-size:11px;font-weight:bold;color:${C.ink};letter-spacing:.5px;">${t}</div>
          <div style="font-size:10px;color:${C.muted};padding-top:2px;">${s}</div>
        </td>
      </tr></table>
    </td>`).join('');

  const preheader = esc((d.introduction || '').slice(0, 140));

  return `<!DOCTYPE html>
<html lang="en" xmlns="http://www.w3.org/1999/xhtml" xmlns:o="urn:schemas-microsoft-com:office:office">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<meta name="x-apple-disable-message-reformatting">
<title>${esc(d.subject || d.brand_name)}</title>
<!--[if mso]><noscript><xml><o:OfficeDocumentSettings><o:PixelsPerInch>96</o:PixelsPerInch></o:OfficeDocumentSettings></xml></noscript><![endif]-->
<style>
  body{margin:0;padding:0;-webkit-text-size-adjust:100%;}
  a{color:${C.ink};}
  @media only screen and (max-width:620px){
    .container{width:100% !important;}
    .stack{display:block !important;width:100% !important;box-sizing:border-box;padding-left:0 !important;padding-right:0 !important;border-right:0 !important;}
    .pad{padding-left:18px !important;padding-right:18px !important;}
    .mast1{font-size:38px !important;line-height:40px !important;}
    .mast2{font-size:44px !important;line-height:46px !important;}
    .hero-wrap{padding-top:20px !important;}
    .hero-img{width:100% !important;height:auto !important;max-width:320px !important;}
  }
</style>
</head>
<body style="margin:0;padding:0;background:${C.page};">
<div style="display:none;max-height:0;overflow:hidden;opacity:0;mso-hide:all;">${preheader}&#8199;&#65279;&#847;&#8199;&#65279;&#847;</div>
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" bgcolor="${C.page}" style="background:${C.page};">
<tr><td align="center" style="padding:24px 10px;">
<table role="presentation" class="container" width="600" cellpadding="0" cellspacing="0" border="0" bgcolor="${C.paper}" style="width:600px;background:${C.paper};border:1px solid ${C.line};">

  ${d.test_mode ? `<tr><td align="center" bgcolor="#FFF3CD" style="background:#FFF3CD;font-family:${SANS};font-size:11px;font-weight:bold;letter-spacing:1px;color:#7A5B00;padding:8px;">${L.test}</td></tr>` : ''}

  <!-- top bar -->
  <tr><td class="pad" style="padding:18px 28px 0 28px;">
    <table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0"><tr>
      <td valign="middle">${logo}</td>
      <td valign="middle" align="right" style="font-family:${SANS};font-size:10px;letter-spacing:2px;color:${C.muted};">AI FOUNDRY &nbsp;·&nbsp; N°${esc(d.issue_number)}</td>
    </tr></table>
  </td></tr>

  <!-- masthead + AI image -->
  <tr><td class="pad" style="padding:22px 28px 8px 28px;">
    <table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0"><tr>
      <td class="stack" width="300" valign="top" style="padding-right:14px;">
        <table role="presentation" cellpadding="0" cellspacing="0" border="0"><tr>
          <td style="border:1px solid ${C.ink};padding:5px 10px;font-family:${SANS};font-size:10px;letter-spacing:2.5px;color:${C.ink};">${L.tagline}</td>
        </tr></table>
        <div class="mast1" style="font-family:${SERIF};font-size:46px;line-height:48px;font-weight:bold;color:${C.ink};padding-top:18px;letter-spacing:1px;">AI FOUNDRY</div>
        <div class="mast2" style="font-family:${SERIF};font-size:52px;line-height:54px;color:${C.gold};letter-spacing:2px;">WEEKLY</div>
        <table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="margin-top:14px;"><tr>
          <td bgcolor="${C.ink}" style="background:${C.ink};color:${C.white};font-family:${SANS};font-size:10px;letter-spacing:2px;padding:8px 12px;">${L.bar}</td>
        </tr></table>
        <div style="font-family:${SANS};font-size:10px;letter-spacing:1.5px;color:${C.ink};padding-top:16px;white-space:nowrap;">
          <span style="color:${C.gold};">&mdash;&mdash;</span>&nbsp; 📅 &nbsp;${L.week} ${esc(String(d.week_label).toUpperCase())}
        </div>
      </td>
      <td class="stack hero-wrap" width="230" valign="top" align="center">${heroCell}</td>
    </tr></table>
  </td></tr>

  <!-- greeting + intro -->
  <tr><td class="pad" style="padding:22px 28px 6px 28px;">
    <table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0"><tr>
      <td style="border-left:3px solid ${C.gold};padding:4px 0 4px 14px;font-family:${SANS};font-size:14px;line-height:22px;color:${C.ink};">
        <strong>%%GREETING%%</strong><br>${esc(d.introduction)}
      </td>
    </tr></table>
  </td></tr>

  <!-- section title -->
  <tr><td class="pad" style="padding:22px 28px 14px 28px;">
    <table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0"><tr>
      <td width="30%" style="border-bottom:1px solid ${C.gold};font-size:1px;line-height:1px;">&nbsp;</td>
      <td align="center" style="font-family:${SANS};font-size:11px;font-weight:bold;letter-spacing:3px;color:${C.ink};padding:0 12px;white-space:nowrap;">${L.headlines}</td>
      <td width="30%" style="border-bottom:1px solid ${C.gold};font-size:1px;line-height:1px;">&nbsp;</td>
    </tr></table>
  </td></tr>

  <!-- cards -->
  <tr><td class="pad" style="padding:0 28px 4px 28px;">
    <table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0">${grid}</table>
  </td></tr>

  <!-- trending + insights -->
  <tr><td class="pad" style="padding:4px 28px 22px 28px;">
    <table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0"><tr>
      <td class="stack" width="50%" valign="top" style="padding-right:8px;">
        <table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="border:1px solid ${C.line};background:${C.white};border-radius:6px;">
          <tr><td style="padding:0;">
            <table role="presentation" cellpadding="0" cellspacing="0" border="0"><tr>
              <td bgcolor="${C.ink}" style="background:${C.ink};color:${C.white};font-family:${SANS};font-size:11px;font-weight:bold;letter-spacing:2px;padding:9px 14px;border-radius:6px 0 0 0;">${L.trending} 🔥</td>
            </tr></table>
          </td></tr>
          <tr><td style="padding:14px 16px 18px 16px;">
            <div style="font-family:${SANS};font-size:14px;font-weight:bold;color:${C.ink};text-transform:uppercase;line-height:19px;">${esc(d.trending?.title)}</div>
            <div style="font-family:${SANS};font-size:12px;line-height:18px;color:${C.muted};padding-top:8px;">${esc(d.trending?.text)}</div>
          </td></tr>
        </table>
      </td>
      <td class="stack" width="50%" valign="top" style="padding-left:8px;">
        <div style="font-family:${SERIF};font-size:54px;line-height:40px;color:${C.gold};height:34px;">&ldquo;</div>
        ${insights}
      </td>
    </tr></table>
  </td></tr>

  <!-- pillars -->
  <tr><td class="pad" style="padding:0 28px;">
    <table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="border-top:1px solid ${C.line};border-bottom:1px solid ${C.line};"><tr>${pillars}</tr></table>
  </td></tr>

  <!-- footer bar -->
  <tr><td style="padding:22px 0 0 0;">
    <table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0"><tr>
      <td align="center" bgcolor="${C.ink}" style="background:${C.ink};padding:14px 10px;font-family:${SANS};font-size:12px;letter-spacing:2.5px;color:${C.white};">
        ${L.footer1} <span style="color:#7CC4F0;">${L.footer2}</span>
      </td>
    </tr></table>
  </td></tr>

  <!-- legal -->
  <tr><td class="pad" align="center" style="padding:16px 28px 22px 28px;font-family:${SANS};font-size:10px;line-height:15px;color:#8A94A6;">
    You are receiving this email as a member of the AI Foundry group — NTT DATA.<br>
    Summaries and illustration are generated automatically by AI from the cited sources; read the original article for full details.<br>
    <a href="%%UNSUBSCRIBE_URL%%" style="color:#8A94A6;text-decoration:underline;">Unsubscribe</a>
    %%TRACKING_PIXEL%%
  </td></tr>

</table>
</td></tr>
</table>
</body>
</html>`;
}


// ---------------- n8n wrapper ----------------
const d = $('Merge Editorial').first().json;
const img = $input.first().json;
const html = renderNewsletter({ ...d, has_logo: img.has_logo, has_hero: img.has_hero });
return [{ json: { subject: d.subject, html, html_size_kb: Math.round(html.length / 1024) } }];

// Build the recipient list:
//   TEST mode          -> "Test" sheet of the Excel file (fallback: test_recipients in Run Config)
//   source = 'excel'   -> "Recipients" sheet of the Excel file
//   source = 'list'    -> recipients_list from Run Config
// Then: validate emails, skip active = no, remove duplicates and people already sent.
const cfg = $('Run Config').first().json;

const norm = k => String(k).toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-z]/g, '');
const EMAIL_KEYS  = ['email', 'mail', 'emailaddress', 'adresseemail', 'courriel'];
const NAME_KEYS   = ['firstname', 'prenom', 'givenname', 'name', 'nom'];
const ACTIVE_KEYS = ['active', 'actif', 'send', 'envoyer'];
const pick = (row, keys) => {
  for (const [k, v] of Object.entries(row || {})) if (keys.includes(norm(k))) return v;
  return undefined;
};
const isActive = v => v === undefined || v === null || String(v).trim() === '' ||
  ['yes', 'oui', 'true', '1', 'y', 'x', 'active', 'actif'].includes(String(v).trim().toLowerCase());
const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

// Rows read from the Excel file (the sheet depends on TEST_MODE)
const excelRows = $('Read Recipients Excel').all().map(i => i.json);
const excelError = excelRows.length && excelRows[0].error ? excelRows[0].error : null;

let source, raw;
if (cfg.test_mode) {
  if (!excelError && excelRows.some(r => pick(r, EMAIL_KEYS))) {
    source = 'test (Excel "Test" sheet)'; raw = excelRows;
  } else {
    source = 'test (Run Config test_recipients)'; raw = cfg.test_recipients;
  }
} else if (cfg.recipients_source === 'list') {
  source = 'list'; raw = cfg.recipients_list;
} else {
  source = 'excel ("Recipients" sheet)';
  if (excelError) {
    throw new Error(`Excel file not found or unreadable (${cfg.recipients_file}): ${excelError}`);
  }
  raw = excelRows;
}

// Test mode can be re-sent as often as needed; real mode never sends twice
const alreadySent = new Set(cfg.test_mode ? [] :
  $('Get Already Sent').all().map(i => String(i.json.subscriber_email || '').toLowerCase()).filter(Boolean));

const seen = new Set();
const invalid = [];
let skippedInactive = 0, skippedAlreadySent = 0;
const list = [];

for (const r of raw || []) {
  const email = String(pick(r, EMAIL_KEYS) ?? '').trim().toLowerCase();
  if (!email) continue;
  if (!EMAIL_RE.test(email)) { invalid.push(email); continue; }
  if (!isActive(pick(r, ACTIVE_KEYS))) { skippedInactive++; continue; }
  if (seen.has(email)) continue;
  seen.add(email);
  if (alreadySent.has(email)) { skippedAlreadySent++; continue; }
  list.push({ email, first_name: String(pick(r, NAME_KEYS) ?? '').trim(), unsubscribe_token: '' });
}

if (!list.length) {
  throw new Error(`No recipients to send to (source: ${source}). ` +
    `Inactive: ${skippedInactive}, already received: ${skippedAlreadySent}, invalid: ${invalid.length}.`);
}

const stats = { source, invalid_emails: invalid, skipped_inactive: skippedInactive, skipped_already_sent: skippedAlreadySent };
return list.map(r => ({ json: { ...r, recipient_stats: stats } }));

const tpl = $('Render HTML Template').first().json;
const images = $('Collect Images').first().binary || {};
const cfg = $('Run Config').first().json;
const esc = s => String(s ?? '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');

const first = String($json.first_name || '').trim().split(/\s+/)[0];
const greeting = first ? `Hello ${esc(first)},` : 'Hello,';

const unsubscribe = (cfg.unsubscribe_base_url && $json.unsubscribe_token)
  ? `${cfg.unsubscribe_base_url}?token=${encodeURIComponent($json.unsubscribe_token)}`
  : `mailto:${cfg.sender_email}?subject=${encodeURIComponent('Unsubscribe ' + cfg.brand_name)}`;

const pixel = (cfg.tracking_base_url && $json.unsubscribe_token)
  ? `<img src="${cfg.tracking_base_url}/open?nid=${encodeURIComponent(cfg.newsletter_id)}&t=${encodeURIComponent($json.unsubscribe_token)}" width="1" height="1" alt="" style="display:block;border:0;width:1px;height:1px;">`
  : '';

const html = tpl.html
  .replaceAll('%%GREETING%%', greeting)
  .replaceAll('%%UNSUBSCRIBE_URL%%', esc(unsubscribe))
  .replaceAll('%%TRACKING_PIXEL%%', pixel);

return { json: { email: $json.email, subject: tpl.subject, html }, binary: images };

const p = $('Personalize Email').item.json;
const cfg = $('Run Config').first().json;
const failed = !!$json.error;
return {
  json: {
    newsletter_id: cfg.newsletter_id,
    email: p.email,
    status: failed ? 'failed' : 'sent',
    error: failed ? String($json.error).slice(0, 300) : '',
  },
};

